export const SLEEP_TRACKER_TRANSLATIONS: Record<SleepTrackerLocale, Catalog> = { de, en, es };
export const getSleepTrackerLocaleTag = (locale: SleepTrackerLocale) => ({ de: 'de-DE', en: 'en-US', es: 'es-ES' })[locale];
export const translateSleepTrackerText = (locale: SleepTrackerLocale, key: SleepTrackerTranslationKey, params: Record<string, string | number> = {}) =>
  (SLEEP_TRACKER_TRANSLATIONS[locale]?.[key] ?? de[key] ?? key).replace(/\{\{(\w+)\}\}/g, (_, token: string) => String(params[token] ?? `{{${token}}}`));
